  name: "unwrap_below_budget_silent",
  ir_version: 1,
  internMode: "dict",
  ddl,
  rel_columns,
  rel_physical_names,
  rel_column_types,
  arrival_targets,
  boot: SUBSCRIBED_BOOT,
  final_select,
  host_plans,
  bind_plans,
  query_plans,
  subscribed_rels,
  rel_catalog,
  enum_types: ENUM_TYPES,
  enum_ref_columns: ENUM_REF_COLUMNS,
  unsupported_execution,
